/**
 * A query optimizer that optimize disjunctive constraints on tuple expressions. Currently, this optimizer {@link Union
 * unions} clones of a repeatable basic tuple expression when the two branches of an {@link Or} are mutually exclusive
 * {@link SameTerm} checks against different fixed RDF values.
 *
 * @author Arjohn Kampman
 * @author James Leigh
 */
public class DisjunctiveConstraintOptimizer implements QueryOptimizer {

	@Override
	public void optimize(TupleExpr tupleExpr, Dataset dataset, BindingSet bindings) {
		tupleExpr.visit(new OrSameTermOptimizer());
	}

	private static class OrSameTermOptimizer extends AbstractSimpleQueryModelVisitor<RuntimeException> {

		protected OrSameTermOptimizer() {
			super(false);
		}

		@Override
		public void meet(Filter filter) {
			if (filter.getClass() == Filter.class
					&& filter.getCondition()instanceof Or orNode
					&& orNode.getClass() == Or.class) {
				TupleExpr filterArg = filter.getArg();
				TupleExpr node = findNotFilter(filterArg);
				SameTermConstraint leftConstraint = getConstraint(orNode.getLeftArg());
				SameTermConstraint rightConstraint = getConstraint(orNode.getRightArg());

				if (leftConstraint == null || rightConstraint == null
						|| !leftConstraint.variableName().equals(rightConstraint.variableName())
						|| leftConstraint.value().equals(rightConstraint.value())
						|| !intermediateFiltersAreRepeatable(filterArg)
						|| !AlgebraEvaluationSafety.isRepeatable(node)) {
					super.meet(filter);
					return;
				}

				QueryModelNode parent = filter.getParentNode();
				boolean scopeChange = filter.isVariableScopeChange();
				scopeChange |= TupleExprs.isVariableScopeChange(node);
				if (filter.isVariableScopeChange() && filterArg instanceof Filter intermediateFilter) {
					// The intermediate filter becomes the group root and must keep the group's scope.
					intermediateFilter.setVariableScopeChange(true);
				}

				// Splitting overlapping predicates into UNION branches would duplicate rows.
				filter.replaceWith(filterArg);

				// Push UNION down below other filters to avoid cloning them
				Filter leftFilter = new Filter(node.clone(), orNode.getLeftArg());
				Filter rightFilter = new Filter(node.clone(), orNode.getRightArg());
				Union union = new Union(leftFilter, rightFilter);
				union.setVariableScopeChange(scopeChange);
				node.replaceWith(union);

				if (parent != null) {
					parent.visit(this);
				} else {
					union.visit(this);
				}
			} else {
				super.meet(filter);
			}
		}

		private TupleExpr findNotFilter(TupleExpr node) {
			if (node instanceof Filter) {
				return findNotFilter(((Filter) node).getArg());
			}
			return node;
		}

		private boolean intermediateFiltersAreRepeatable(TupleExpr node) {
			while (node instanceof Filter intermediateFilter) {
				if (!AlgebraEvaluationSafety.isRepeatable(intermediateFilter.getCondition())) {
					return false;
				}
				node = intermediateFilter.getArg();
			}
			return true;
		}

		private SameTermConstraint getConstraint(ValueExpr expression) {
			if (expression.getClass() != SameTerm.class) {
				return null;
			}
			SameTerm sameTerm = (SameTerm) expression;

			if (sameTerm.getLeftArg()instanceof Var variable
					&& isPlainVariable(variable)
					&& sameTerm.getRightArg().getClass() == ValueConstant.class
					&& sameTerm.getRightArg()instanceof ValueConstant constant) {
				return new SameTermConstraint(variable.getName(), constant.getValue());
			}

			if (sameTerm.getRightArg()instanceof Var variable
					&& isPlainVariable(variable)
					&& sameTerm.getLeftArg().getClass() == ValueConstant.class
					&& sameTerm.getLeftArg()instanceof ValueConstant constant) {
				return new SameTermConstraint(variable.getName(), constant.getValue());
			}

			return null;
		}

		private boolean isPlainVariable(Var variable) {
			return variable.getName() != null && !variable.hasValue() && !variable.isConstant()
					&& !variable.isAnonymous();
		}

		private record SameTermConstraint(String variableName, Value value) {
		}
	}
}
